solutions.naive:
class Solution:
    def smallestDivisor(self, nums: list[int], threshold: int) -> int:
        for d in range(1, max(nums) + 1):
            total = 0
            for x in nums:
                total += (x + d - 1) // d
            if total <= threshold:
                return d
        return max(nums)

solutions.better:
class Solution:
    def smallestDivisor(self, nums: list[int], threshold: int) -> int:
        def ok(d: int) -> bool:
            return sum((x + d - 1) // d for x in nums) <= threshold
        lo, hi = 1, max(nums)
        while lo < hi:
            mid = (lo + hi) // 2
            if ok(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo

