class Solution:
    def smallestDivisor(self, nums: list[int], threshold: int) -> int:
        lo, hi = 1, max(nums)
        while lo < hi:
            mid = (lo + hi) // 2
            total = 0
            for x in nums:
                total += (x + mid - 1) // mid
                if total > threshold:
                    break
            if total <= threshold:
                hi = mid
            else:
                lo = mid + 1
        return lo

